# P0-D: provision a REAL upstream Laravel app for smoke tests (Windows dev).
# The app itself is never modified (deployment config only: .env already
# generated by create-project). Idempotent: skips when provisioned.
$ErrorActionPreference = 'Stop'
$Dir = if ($env:PHPX_LARAVEL_DIR) { $env:PHPX_LARAVEL_DIR } else { 'data/smoke/laravel' }
if ((Test-Path "$Dir/public/index.php") -and (Test-Path "$Dir/vendor/autoload.php") -and (Test-Path "$Dir/.env")) {
  Write-Host "[laravel-smoke] already provisioned at $Dir"
  exit 0
}
$env:COMPOSER_NO_INTERACTION = '1'
$env:COMPOSER_ALLOW_SUPERUSER = '1'
if (-not (Get-Command composer -ErrorAction SilentlyContinue)) { Write-Error 'composer not found in PATH'; exit 2 }
if (-not (Get-Command php -ErrorAction SilentlyContinue)) { Write-Error 'php not found in PATH'; exit 2 }
if (Test-Path $Dir) {
  Write-Host "[laravel-smoke] incomplete install at $Dir, recreating..."
  Remove-Item -Recurse -Force $Dir
}
composer create-project 'laravel/laravel:^12.0' "$Dir" --prefer-dist --no-progress --no-interaction
$ver = (& php "$Dir/artisan" --version) 2>$null
Write-Host "[laravel-smoke] ready at $Dir ($ver)"
